function App() {
  const [items, setItems] = useState([
    { id: 'a', name: 'Apple' },
    { id: 'b', name: 'Banana' },
    { id: 'c', name: 'Cherry' }
  ]);
  const shuffle = () => setItems(prev => [...prev].reverse());
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={shuffle}>Reverse order</button>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {items.map(item => (
          <li key={item.id} style={{ margin: '6px 0' }}>
            {item.name}: <input placeholder="type a note" />
          </li>
        ))}
      </ul>
      <p style={{ color: '#666' }}>Notes follow their row because key=item.id.</p>
    </div>
  );
}

