function App() {
  const [items, setItems] = useState([
    { id: 'p1', title: 'Pricing' },
    { id: 'p2', title: 'Billing' },
    { id: 'p3', title: 'Refunds' }
  ]);
  const [expandedId, setExpandedId] = useState(null);
  const reverse = () => setItems(prev => [...prev].reverse());
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={reverse}>Reverse</button>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {items.map(item => (
          <li key={item.id} style={{ borderBottom: '1px solid #eee', padding: '6px 0' }}>
            <button onClick={() => setExpandedId(id => (id === item.id ? null : item.id))}>
              {item.title}
            </button>
            {expandedId === item.id && <p style={{ margin: '4px 0', color: '#555' }}>Details for {item.title}</p>}
          </li>
        ))}
      </ul>
    </div>
  );
}
